51	function createRegexpMatcher(query: string): Matcher {
52	    let expression: RegExp
53	
54	    try {
55	        expression = new RegExp(query)
56	    } catch (error) {
57	        throw new InvalidSearchPatternError(error instanceof Error ? error.message : 'Invalid regular expression')
58	    }
59	
60	    return {
61	        find(text: string) {
62	            const found = text.match(expression)
63	
64	            return found?.index === undefined ? null : { index: found.index, length: found[0].length }
65	        },
66	    }
67	}
