152	function backgroundGroupKey(path: string, workingFolder: string, specialFolderPaths: string[]): string {
153	    const normalized = path.replace(/\\/gu, '/')
154	    const specialFolder = specialFolderPaths
155	        .map((folder) => folder.replace(/\\/gu, '/').replace(/^\/+|\/+$/gu, ''))
156	        .find((folder) => normalized === folder || normalized.startsWith(`${folder}/`))
157	    if (specialFolder) return folderName(specialFolder)
158	
159	    const prefix = `${workingFolder}/`
160	    const rest = normalized.startsWith(prefix) ? normalized.slice(prefix.length) : normalized
161	    const segments = rest.split('/')
