166	function groupBackgroundMatches(matches: SearchMatch[], workingFolder: string, specialFolderPaths: string[]): BackgroundGroup[] {
167	    const groups: BackgroundGroup[] = []
168	    const byFolder = new Map<string, BackgroundGroup>()
169	
170	    for (const match of matches) {
171	        const folder = backgroundGroupKey(match.path, workingFolder, specialFolderPaths)
172	        const existing = byFolder.get(folder)
173	
174	        if (existing) {
175	            existing.matches.push(match)
176	            continue
177	        }
178	
179	        const group: BackgroundGroup = { folder, matches: [match] }
180	        byFolder.set(folder, group)
181	        groups.push(group)
182	    }
