187	/**
188	 * Searches a loaded project snapshot. Active cards are matched by header fields and full body;
189	 * background cards are matched by header fields, and by body only when `includeBackgroundBody` is set.
190	 * Throws {@link InvalidSearchPatternError} for an invalid RegExp-mode query.
191	 */
192	export function searchProject(
193	    snapshot: ProjectSnapshot,
194	    query: string,
195	    options: SearchOptions,
196	    specialFolderPaths: string[] = [],
197	): SearchResults {
198	    if (query.trim().length === 0) return { active: [], actions: [], backgroundGroups: [] }
199	
200	    const matcher = createMatcher(query, options)
201	    const active = snapshot.activeCards
202	        .map((card) => matchCard(card, matcher, true))
203	        .filter((match): match is SearchMatch => match !== null)
204	    const backgroundMatches = snapshot.backgroundCards
205	        .map((card) => matchCard(card, matcher, options.includeBackgroundBody))
206	        .filter((match): match is SearchMatch => match !== null)
207	
208	    return {
209	        active,
210	        actions: [],
211	        backgroundGroups: groupBackgroundMatches(backgroundMatches, snapshot.workingFolder, specialFolderPaths),
212	    }
213	}
